// Exact excerpts generated by the CPU fixture, no real model or customer data.
async page=>{
  const base='http://10.0.3.2:8769',checks=[];
  const check=(ok,label)=>{if(!ok)throw Error(label);checks.push(label);};
  const value=await(await page.request.get(base+'/fixture/procedure-review')).json();
  await page.goto(base+'/#/assistant');await page.waitForFunction(()=>typeof renderText==='function'&&S.authReady&&S.user);
  const observed=await page.evaluate(value=>{
    document.querySelector('#chat-messages').replaceChildren();
    const rendered=message('assistant',value.answer,value.sources,'Essai fictif');rendered.node.id='procedure-review-fixture';const target=rendered.body;
    return {unsafe:!!target.querySelector('img,script,iframe'),quote:target.querySelector('blockquote')?.textContent,
      citations:target.querySelectorAll('button.citation').length,quotedCitation:!!target.querySelector('blockquote button.citation'),
      command:[...target.querySelectorAll('code')].some(node=>node.textContent==='MENU → 27'),
      first:target.firstElementChild?.textContent};
  },value);
  check(!observed.unsafe,'Le balisage documentaire reste du texte');
  check(observed.quote?.includes('<img src=x> [1]'),'Les mots et crochets du document sont conservés');
  check(observed.citations===2&&!observed.quotedCitation,'Les crochets du document ne créent pas de fausse référence');
  check(observed.command,'La commande littérale est conservée');
  check(observed.first?.includes('À vérifier avant de commencer'),'La condition est affichée avant les étapes');
  for(const width of [1366,390,320]){await page.setViewportSize({width,height:844});check(!await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),'Extrait sans débordement à '+width);}
  return {checks:checks.length,results:checks};
}
